sysevent_script_action.script:
(function() {
    var configSysId = event.parm1;

    if (gs.nil(configSysId)) {
        gs.error('[IllumioPostSyncDiscovery] No configSysId in event.parm1');
        return;
    }

    gs.info('[IllumioPostSyncDiscovery] Starting post-sync discovery for config: ' + configSysId);

    var result = new IllumioStartDiscovery().process(configSysId, true);

    if (!result) {
        gs.warn('[IllumioPostSyncDiscovery] Discovery failed to start for config ' + configSysId);
    }
})();
